@Component("bIQuery-handler")
@ProcessingGroup("bIQuery-processing-group")
public class BIQueryEventHandler {
	
	// core constructor
	BIQueryEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBIQueryEvent
     */
    @EventHandler
    public void handle( CreateBIQueryEvent event) {
        entityManager.persist(new BIQuery(event.getBIQueryId(), event.getName(), event.getText(), event.getWorkspace(), event.getDatasets(), event.getReports(), event.getDashboards(), event.getNotebooks(), event.getDialect()));
    }

    /*
     * @param	event UpdateBIQueryEvent
     */
    @EventHandler
    public BIQuery handle( UpdateBIQueryEvent event) {
    	entityManager.merge(new BIQuery(event.getBIQueryId(), event.getName(), event.getText(), event.getWorkspace(), event.getDatasets(), event.getReports(), event.getDashboards(), event.getNotebooks(), event.getDialect()));
    }
    
    /*
     * @param	event DeleteBIQueryEvent
     */
    @EventHandler
    public void on( DeleteBIQueryEvent event) {
    	BIQuery entity = new BIQuery();
   
    	// ------------------------------------------
    	// apply the BIQueryId
    	// ------------------------------------------
    	entity.setBIQueryId( event.getBIQueryId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BIQueryRepository bIQueryEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BIQueryEventHandler.class.getName());

}
